<?php require 'includes/functions.php';$u=auth();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(!in_array(post('type'),['access','delete'],true)||mb_strlen(post('details'))>2000)$error='ข้อมูลคำขอไม่ถูกต้อง';else{q('INSERT INTO privacy_requests(user_id,type,details) VALUES (?,?,?)',[$u['id'],post('type'),post('details')]);flash('รับคำขอแล้ว ผู้ดูแลจะพิจารณาตามนโยบายและติดต่อผ่านอีเมลบัญชี');go('privacy_request.php');}}require 'includes/header.php';?><div class="form-card"><h1><?=e(t('คำขอข้อมูลส่วนบุคคล'))?></h1><p><?=e(t('ส่งคำขอเข้าถึงหรือขอลบข้อมูลของบัญชีนี้'))?></p><p class="error"><?=e(t($error))?></p><form method="post"><?=csrf()?><label><?=e(t('ประเภทคำขอ'))?><select name="type"><option value="access"><?=e(t('ขอเข้าถึงข้อมูล'))?></option><option value="delete"><?=e(t('ขอลบข้อมูล'))?></option></select></label><label><?=e(t('รายละเอียด'))?><textarea name="details" maxlength="2000"></textarea></label><button><?=e(t('ส่งคำขอ'))?></button></form><?php foreach(q('SELECT type,status,created_at FROM privacy_requests WHERE user_id=? ORDER BY id DESC',[$u['id']]) as $r):?><p><?=e($r['type']==='access'?'ขอเข้าถึงข้อมูล':'ขอลบข้อมูล')?> · <?=e($r['status'])?> · <?=e($r['created_at'])?></p><?php endforeach ?></div><?php require 'includes/footer.php';?>
